/* Tipoca City dome platform: white rings, a lit dome cap and support struts. */
function drawKaminoDome(ctx, x, y, r, S, rng) {
  ctx.save();
  ctx.translate(x, y);

  // cast shadow on the water
  ctx.fillStyle = 'rgba(0, 9, 18, 0.42)';
  ctx.beginPath();
  ctx.ellipse(r * 0.16, r * 0.24, r * 1.16, r * 1.02, 0.1, 0, TAU);
  ctx.fill();

  // outer landing ring
  const rim = ctx.createRadialGradient(-r * 0.3, -r * 0.32, r * 0.08, 0, 0, r);
  rim.addColorStop(0, '#f7fbfc');
  rim.addColorStop(0.6, '#d9e4ea');
  rim.addColorStop(1, '#9dafba');
  ctx.fillStyle = rim;
  ctx.beginPath();
  ctx.arc(0, 0, r, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = '#7f93a0';
  ctx.lineWidth = 1.4 * S;
  ctx.stroke();

  // service ring and radial struts
  ctx.strokeStyle = 'rgba(255, 255, 255, 0.75)';
  ctx.lineWidth = 1.6 * S;
  ctx.beginPath();
  ctx.arc(0, 0, r * 0.78, 0, TAU);
  ctx.stroke();
  ctx.strokeStyle = 'rgba(108, 136, 152, 0.4)';
  ctx.lineWidth = 1.1 * S;
  for (let i = 0; i < 8; i++) {
    const a = i * TAU / 8 + 0.2;
    ctx.beginPath();
    ctx.moveTo(Math.cos(a) * r * 0.6, Math.sin(a) * r * 0.6);
    ctx.lineTo(Math.cos(a) * r * 0.99, Math.sin(a) * r * 0.99);
    ctx.stroke();
  }

  // dome itself
  const dome = ctx.createRadialGradient(-r * 0.2, -r * 0.24, r * 0.04, 0, 0, r * 0.62);
  dome.addColorStop(0, '#ffffff');
  dome.addColorStop(0.5, '#dce8ee');
  dome.addColorStop(1, '#8fa5b2');
  ctx.fillStyle = dome;
  ctx.beginPath();
  ctx.arc(0, 0, r * 0.6, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = 'rgba(255, 255, 255, 0.85)';
  ctx.lineWidth = 1.3 * S;
  ctx.beginPath();
  ctx.arc(0, 0, r * 0.6, -2.5, -0.6);
  ctx.stroke();
  // dome seam
  ctx.strokeStyle = 'rgba(118, 144, 160, 0.45)';
  ctx.lineWidth = 1 * S;
  ctx.beginPath();
  ctx.arc(0, 0, r * 0.42, 0, TAU);
  ctx.stroke();

  // lit windows around the base
  ctx.save();
  ctx.shadowColor = 'rgba(132, 224, 255, 0.85)';
  ctx.shadowBlur = 5 * S;
  ctx.fillStyle = 'rgba(178, 242, 255, 0.9)';
  for (let i = 0; i < 6; i++) {
    const a = i * TAU / 6 + 0.5;
    ctx.beginPath();
    ctx.arc(Math.cos(a) * r * 0.68, Math.sin(a) * r * 0.68, Math.max(0.7 * S, r * 0.028), 0, TAU);
    ctx.fill();
  }
  ctx.restore();
  ctx.restore();
}

/* Slender city spire seen from above: stacked white rings climbing to a point. */
function drawKaminoSpire(ctx, x, y, r, S, rng) {
  ctx.save();
  ctx.translate(x, y);

  ctx.fillStyle = 'rgba(0, 9, 18, 0.38)';
  ctx.beginPath();
  ctx.ellipse(r * 0.34, r * 0.4, r * 0.96, r * 0.42, 0.35, 0, TAU);
  ctx.fill();

  for (let i = 0; i < 4; i++) {
    const rr = r * (1 - i * 0.19);
    const shade = 0.9 - i * 0.06;
    ctx.fillStyle = `rgba(${224 * shade + 12}, ${235 * shade + 12}, ${242 * shade + 10}, 1)`;
    ctx.beginPath();
    ctx.arc(-i * r * 0.06, -i * r * 0.07, rr, 0, TAU);
    ctx.fill();
    ctx.strokeStyle = `rgba(110, 138, 154, ${0.3 + i * 0.08})`;
    ctx.lineWidth = 1 * S;
    ctx.stroke();
  }

  ctx.fillStyle = '#f8fcfd';
  ctx.beginPath();
  ctx.arc(-r * 0.18, -r * 0.21, r * 0.16, 0, TAU);
  ctx.fill();
  ctx.strokeStyle = 'rgba(130, 220, 250, 0.7)';
  ctx.lineWidth = 1.2 * S;
  ctx.stroke();

  // signal light
  ctx.save();
  ctx.shadowColor = 'rgba(255, 92, 72, 0.9)';
  ctx.shadowBlur = 7 * S;
  ctx.fillStyle = 'rgba(255, 120, 98, 0.95)';
  ctx.beginPath();
  ctx.arc(-r * 0.18, -r * 0.21, Math.max(0.8 * S, r * 0.045), 0, TAU);
  ctx.fill();
  ctx.restore();
  ctx.restore();
}

