  ctx.save();
  ctx.lineCap = 'round';
  const layers = [
    { count: 110, speed: 640, len: 16, alpha: 0.20, width: 1.0, slant: 0.26 },
    { count: 70, speed: 900, len: 26, alpha: 0.30, width: 1.5, slant: 0.3 },
  ];
