+  ctx.beginPath();
+  ctx.moveTo(-len * 0.44, -wide * 0.38);
+  ctx.lineTo(len * 0.44, -wide * 0.38);
+  ctx.stroke();
+  ctx.save();
+  ctx.shadowColor = 'rgba(255, 160, 60, 0.9)';
+  ctx.shadowBlur = 6 * S;
+  ctx.fillStyle = 'rgba(255, 190, 92, 0.95)';
+  ctx.beginPath();
+  ctx.arc(len * 0.46, 0, 1.25 * S, 0, TAU);
+  ctx.fill();
+  ctx.restore();
