+  // scorch marks under the joints
+  ctx.fillStyle = 'rgba(46, 16, 8, 0.35)';
+  for (const t of [-0.24, 0.24]) {
+    ctx.beginPath();
+    ctx.ellipse(len * t, wide * 1.15, r * 0.52, wide * 0.35, 0, 0, TAU);
+    ctx.fill();
+  }
+  ctx.restore();
