      type: spec.type,
      hp: spec.hp,
      maxHp: spec.hp,
      speed: spec.speed * (0.95 + Math.random() * 0.1),
      t: 0,
      x: this.pathPts[0][0],
      y: this.pathPts[0][1],
      angle: 0,
      radius: def.radius,
      slowT: 0,
      slowFactor: 0,
      hitFlash: 0,
      phase: Math.random() * TAU,
      waterTrailTimer: 0,
      dead: false,
      reward: enemyReward(spec.type, this.waveNumber),
      leak: def.leak,
      isBoss: !!def.boss,
    };
    this.positionEnemy(e);
    this.enemies.push(e);
    this.waveSpawned++;
    if (e.isBoss) {
      this.bossRef = e;
      this.audio.bossWarn();
      this.shake = Math.max(this.shake, 5);
