  syncUI(true);
}

function restartRun() {
  runFinished = false;
  pauseModal.classList.add('hidden');
  endScreen.classList.add('hidden');
  hideMenuScreens();
  game.reset();
  game.started = true;
  game.paused = false;
  game.speed = 1;
  selectedType = null;
  drag = null;
  closeInspector(true);
  setArmed(null);
  dragGhost.classList.add('hidden');
  placeHint.classList.add('hidden');
  syncUI(true);
  audio.ensure();
  toast('Wave 1 ready — drag a tower from the hangar', 'good');
}

function quitToMap() {
  runFinished = false;
  pauseModal.classList.add('hidden');
  endScreen.classList.add('hidden');
  cancelPlacement(true);
  closeInspector(true);
  game.reset();
  game.started = false;
  game.paused = false;
  selectedType = null;
  drag = null;
  setArmed(null);
  dragGhost.classList.add('hidden');
  placeHint.classList.add('hidden');
