content.text:
Now replace the nextWaveBtn click handler with the full auto logic. We'll insert functions before the handler. Code:

```
/* ---------------- wave launch & auto-start ---------------- */

const nextWaveBtn = $('#nextWaveBtn');
let suppressSendClick = false;
let sendHoldTimer = 0;
let sendHoldReady = false;

function launchWave(fromAuto = false) {
  if (!game.started || game.paused) return false;
  if (game.phase !== 'build' || game.waveActive) return false;
  if (!fromAuto) cancelPlacement(true);
  const started = game.startWave();
  if (started) {
    audio.ui();
    toast(`Wave ${game.waveNumber} incoming${fromAuto ? ' — auto-start' : ''}`, 'bad');
    syncUI(true);
  }
  return started;
}

function setAutoWave(next, announce = true) {
  if (!game.started || game.phase === 'victory' || game.phase === 'defeat') return;
  if (!!next === autoWave) return;
  autoWave = !!next;
  autoWaveTimer = AUTO_WAVE_DELAY;
  nextWaveBtn.classList.toggle('auto', autoWave);
  nextWaveBtn.setAttribute('aria-pressed', String(autoWave));
  if (announce) {
    audio.ui();
    toast(autoWave ? 'Auto-start engaged — waves launch automatically' : 'Auto-start disengaged', 'good');
  }
  syncUI(true);
}

function resetAutoWave() {
  autoWave = false;
  autoWaveTimer = AUTO_WAVE_DELAY;
  if (nextWaveBtn) {
    nextWaveBtn.classList.remove('auto', 'holding', 'hold-ready');
    nextWaveBtn.setAttribute('aria-pressed', 'false');
  }
}

function updateAutoWave(dt) {
  if (!autoWave || !game.started || game.paused) return;
  if (game.phase !== 'build') {
    autoWaveTimer = AUTO_WAVE_DELAY;
    return;
  }
  autoWaveTimer -= dt;
  if (autoWaveTimer <= 0) {
    autoWaveTimer = AUTO_WAVE_DELAY;
    launchWave(true);
  }
}

nextWaveBtn.addEventListener('click', (e) => {
  if (suppressSendClick) {
    suppressSendClick = false;
    e.preventDefault();
    return;
  }
  if (!game.started) return;
  if (autoWave) {
    setAutoWave(false);
    return;
  }
  launchWave(false);
});

nextWaveBtn.addEventListener('pointerdown', (e) => {
  if (!game.started) return;
  if (e.button != null && e.button !== 0) return;
  sendHoldReady = false;
  nextWaveBtn.classList.add('holding');
  clearTimeout(sendHoldTimer);
  sendHoldTimer = window.setTimeout(() => {
    sendHoldReady = true;
    nextWaveBtn.classList.add('hold-ready');
  }, AUTO_HOLD_MS);
});

function endSendHold(commit) {
  if (!sendHoldTimer && !sendHoldReady) return;
  clearTimeout(sendHoldTimer);
  sendHoldTimer = 0;
  nextWaveBtn.classList.remove('holding', 'hold-ready');
  if (commit && sendHoldReady) {
    suppressSendClick = true;
    window.setTimeout(() => { suppressSendClick = false; }, 500);
    sendHoldReady = false;
    toggleAutoWave();
  } else {
    sendHoldReady = false;
  }
}

nextWaveBtn.addEventListener('pointerup', () => endSendHold(true));
nextWaveBtn.addEventListener('pointercancel', () => endSendHold(false));
nextWaveBtn.addEventListener('pointerleave', () => endSendHold(false));

function toggleAutoWave() {
  if (!game.started) return;
  setAutoWave(!autoWave);
}
```

Wait: `nextWaveBtn.addEventListener('click')` and `endSendHold` use `toggleAutoWave` declared as a function declaration later (hoisted) fine.

Important bug: when long press completes, `sendClick` may also fire; suppress flag set true in endSendHold. Good.

But `setAutoWave` early return if value equals autoWave. When user long presses while auto off, toggles on. Fine. When auto on and they long press, toggles off. Fine.

`updateAutoWave(dt)`: if game phase is build but game.paused false; launchWave checks pause again. Fine.

But timer starts counting immediately when auto enabled during build, before the release? We set timer on toggle after release. Good.

Potential issue: `endSendHold(false)` due to pointerleave may occur when the user presses and the browser fires pointerleave because the button is disabled? Disabled buttons can still have pointerdown? If disabled, pointer events aren't targeted. Fine.

Long press while auto is on and in wave: autoWave true, phase wave; button not disabled. pointerdown → hold → release → setAutoWave(false). Works; click suppressed.

Do we need to handle a `click` that occurs after a long press but where `suppressSendClick` got cleared by timeout before click? Pointerup and click are synchronous in the same task, so 500ms is plenty.

One more: if the user long-presses and then drags off, endSendHold(false) (pointerleave) clears timer; but if timer already fired, sendHoldReady true; commit false → resets. Good. No click.

Now the existing click handler block must be replaced. Let's find exact text and replace. Then add updateAutoWave call in loop. Then reset calls.

Also add keyboard 'a' toggle in keydown, after "p"/"m" handling.

Let's apply.

