  setMap(id) {
    const next = getMap(id);
    if (this.map && this.map.id === next.id) return;
    this.map = next;
    this.theme = getTheme(next.theme);
    this.reset();
    if (this.w > 1) this.resize(this.w, this.h, this.dpr);
  }

  reset() {
    const map = this.map || getMap('tatooine');
    this.credits = map.startCredits ?? START_CREDITS;
    this.lives = map.startLives ?? START_LIVES;
    this.waveNumber = 1;
    this.waveActive = false;
    this.spawnQueue = null;
    this.spawnTimer = 0;
    this.waveTotal = 0;
    this.waveSpawned = 0;
    this.enemies = [];
    this.towers = [];
    this.projectiles = [];
    this.particles = [];
    this.effects = [];
    this.kills = 0;
    this.creditsEarned = 0;
    this.selected = null;
    this.pendingType = null;
    this.preview = null;
    this.phase = 'build';
    this.endless = false;
    this.bossRef = null;
    this.shake = 0;
    this.baseFlash = 0;
    this.dustTimer = 0;
    this.spawnPoint = [0, 0];
  }

  resize(w, h, dpr) {
    this.dpr = dpr;
    this.w = Math.max(1, w);
    this.h = Math.max(1, h);
    this.canvas.width = Math.floor(this.w * dpr);
    this.canvas.height = Math.floor(this.h * dpr);
    this.ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
    this.S = clamp(Math.min(this.w / 960, this.h / 640), 0.58, 1.55);
    this.pathPts = samplePath(this.map.path, this.w, this.h);
    let len = 0;
    for (let i = 1; i < this.pathPts.length; i++) {
      len += Math.hypot(this.pathPts[i][0] - this.pathPts[i - 1][0], this.pathPts[i][1] - this.pathPts[i - 1][1]);
    }
    this.pathLen = Math.max(1, len);
    this.spawnPoint = this.pathPts[0] || [0, 0];
    this.bg = buildBackground(this.w, this.h, this.pathPts, this.S, Math.min(dpr, 2), this.map);
    for (const t of this.towers) {
      t.x = t.nx * this.w;
      t.y = t.ny * this.h;
    }
    for (const e of this.enemies) {
      this.positionEnemy(e);
    }
  }

  begin() {
    if (this.started) return;
    this.started = true;
    this.phase = 'build';
    this.credits = this.map.startCredits ?? START_CREDITS;
    this.lives = this.map.startLives ?? START_LIVES;
  }

  setSpeed(s) {
    this.speed = s;
  }

  /* ---------------- path & placement ---------------- */

  pathWidth() {
    const lane = this.map && this.map.theme === 'ocean' ? 29 : 34;
    return clamp(lane * this.S, 24, 54);
  }
  if (sendHoldEngaged) {
    // The hold already toggled auto mode; swallow the trailing click so it
    // does not immediately turn auto back off.
    suppressSendClick = true;
    window.setTimeout(() => { suppressSendClick = false; }, 450);
  }
  sendHoldEngaged = false;
}

