    ? `Auto waves engaged — wave ${game.waveNumber} incoming`
    : 'Auto waves engaged — the next wave launches automatically', 'good');
  syncUI(true);
}

function toggleAutoWave() {
  if (!game.started) return;
  if (autoArming) { cancelAutoArm(); return; }
